module LBDPTest

import ..Main: h1, h2

@info h1("LBDP with soft proposals")

using Test
using BenchmarkTools
using Random: seed!
using PhyloPOMP
import PartiallyObservedMarkovProcesses as POMP

heavy = occursin(r"y|yes|t|true", get(ENV,"RUN_HEAVY_TESTS","no"))

"""
   A soft filter for LBDP.
"""
const mgp = @mgp_soft_filter(
    demes=(def,), deme_occupancy=(n,),
    state=(n,), enns=(n,), ells=(ℓ,),
    jumps=(
        birth=(
            rate=λ*n, popmove=(n += 1),
            moves=(
                reg=(
                    type=id,
                    pi=1-ℓ*(ℓ-1)/n/(n+1),
                    boost=@binomratio(n,ℓ,2,0)+ℓ*@binomratio(n,ℓ,2,1),
                ),
                fork=(
                    type=fork,
                    from=def, to=(def,def),
                    boost=@binomratio(n,ℓ,2,2),
                ),
            ),
        ),
        death=(
            rate=μ*n, popmove=(n -= 1),
            moves=(
                regular=(
                    type=id,
                    pi=@indicator(n>ℓ, 1-ℓ/n),
                ),
            ),
        ),
        sample_nondestruct=(
            rate=ψ*n,
            moves=(
                inline=(
                    type=chop, signature=(1,1),
                    from=def, to=def,
                    boost=@binomratio(n,ℓ,1,1),
                ),
                terminal=(
                    type=chop, signature=(1,0), from=def,
                    boost=@binomratio(n,ℓ,1,0),
                ),
            ),
        ),
        sample_destruct=(
            rate=χ*n, popmove=(n -= 1),
            moves=(
                terminal=(
                    type=chop,
                    signature=(1,0),
                    from=def,
                    boost=@binomratio(n,ℓ,0,0),
                ),
            ),
        ),
    ),
    rinit = function(; n0, _...)
        (n=n0,)
    end,
    init_state=:(n=Int64(0),),
)

